import * as T from './three.module.js';
export const inkMaterial=new T.MeshBasicMaterial({color:'#302f27',side:T.BackSide});
export const toneRamp=(()=>{const t=new T.DataTexture(new Uint8Array([110,160,208,246]),4,1,T.RedFormat);t.minFilter=T.NearestFilter;t.magFilter=T.NearestFilter;t.needsUpdate=true;return t;})();
export function texture(kind){const c=document.createElement('canvas');c.width=512;c.height=512;const g=c.getContext('2d');g.fillStyle=kind==='metal'?'#7e8580':kind==='tile'?'#b5b39a':kind==='stone'?'#aaa38b':'#c3bba0';g.fillRect(0,0,512,512);if(kind==='tile'||kind==='stone'){for(let y=0;y<8;y++)for(let x=0;x<8;x++){g.fillStyle=(x+y)%2?'#8b978a':'#c3c2a8';g.fillRect(x*64+1,y*64+1,62,62);}}else if(kind==='metal'){g.strokeStyle='#454f48';g.lineWidth=3;for(let y=0;y<512;y+=28)for(let x=0;x<512;x+=32){g.beginPath();g.moveTo(x,y+8);g.lineTo(x+12,y);g.stroke();}}else{g.strokeStyle='#91947c';g.lineWidth=2;for(let x=0;x<512;x+=32){g.beginPath();g.moveTo(x,0);g.lineTo(x,512);g.stroke();}for(let y=16;y<512;y+=48)for(let x=16;x<512;x+=32){g.beginPath();g.moveTo(x-4,y);g.lineTo(x,y-6);g.lineTo(x+4,y);g.lineTo(x,y+6);g.closePath();g.stroke();}}for(let i=0;i<4500;i++){const x=(i*73)%512,y=(i*137+Math.floor(i/512)*17)%512;g.fillStyle=i%3?'#39392d0b':'#f6ecc219';g.fillRect(x,y,1,1+(i%3));}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(kind==='paper'?4:5,kind==='paper'?2:7);return t;}
export function portrait(seed=0){const c=document.createElement('canvas');c.width=400;c.height=520;const g=c.getContext('2d');g.fillStyle='#b7b297';g.fillRect(0,0,400,520);g.fillStyle='#747e6c';g.fillRect(26,26,348,468);g.strokeStyle='#32372e';g.lineWidth=5;for(let j=0;j<9;j++){g.beginPath();g.moveTo(35,300+j*13);g.bezierCurveTo(100,250+j*13,280,350+j*13,365,295+j*13);g.stroke();}g.fillStyle='#424a3e';g.beginPath();g.moveTo(74,490);g.lineTo(108,330);g.lineTo(169,298);g.lineTo(230,298);g.lineTo(298,334);g.lineTo(330,490);g.fill();g.fillStyle='#c8b995';g.beginPath();g.ellipse(200,205,67,104,.07,0,Math.PI*2);g.fill();g.stroke();g.fillStyle='#343b30';g.beginPath();g.ellipse(200,126,70,28,0,Math.PI,Math.PI*2);g.fill();g.strokeStyle='#34382e';g.lineWidth=4;for(const x of[173,227]){g.beginPath();g.moveTo(x-12,205);g.lineTo(x+12,205);g.stroke();}g.beginPath();g.moveTo(202,210);g.lineTo(191,252);g.lineTo(210,251);g.moveTo(179,278);g.lineTo(217,278);g.stroke();g.fillStyle='#ddd0a8';g.beginPath();g.arc(300,80,21,0,Math.PI*2);g.fill();g.fillStyle='#4e5141';g.font='22px Georgia';g.fillText(['XIV','00:14','014'][seed%3],160,478);for(let i=0;i<8000;i++){g.fillStyle=i%2?'#282e200d':'#f7e7c014';g.fillRect((i*71)%400,(i*131)%520,1,2);}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
